/**
 * Page Object for Admin — System Users
 * Source: cypress/e2e/orangehrm-admin.cy.js
 * Generated by: /tw-e2e-page-object
 *
 * Selector strategy (third-party app — data-testid cannot be added):
 *   1. input[name] / button[type]                             — stable HTML attributes
 *   2. cy.contains('.oxd-label', ...).closest().find()        — label-anchored (stable)
 *   3. cy.contains('button', 'text')                          — text-based (moderate)
 *   REMOVED: .oxd-button--secondary, .eq(0)/.eq(1) index selectors
 *   TODO: If OrangeHRM exposes data-testid, replace label-anchored selectors.
 */
class AdminPage {

    // --- Stable selectors ---
    submitButton = 'button[type="submit"]';
    resetButton  = 'button[type="reset"]'; // kept for reference — use clickReset() which uses text

    // --- Assertions ---

    verifySystemUsersSectionVisible() {
        cy.contains('h5', 'System Users').should('be.visible');
        return this;
    }

    verifySearchFormVisible() {
        cy.get('.oxd-form').should('be.visible');
        return this;
    }

    verifyTableVisible() {
        cy.get('.oxd-table').should('be.visible');
        return this;
    }

    verifyTableHeaders() {
        cy.get('.oxd-table-header').should('be.visible');
        cy.contains('.oxd-table-header-cell', 'Username').should('be.visible');
        cy.contains('.oxd-table-header-cell', 'User Role').should('be.visible');
        cy.contains('.oxd-table-header-cell', 'Employee Name').should('be.visible');
        cy.contains('.oxd-table-header-cell', 'Status').should('be.visible');
        return this;
    }

    // --- Actions ---

    searchForUser(username) {
        // Label-anchored: finds the Username input regardless of DOM position
        cy.contains('.oxd-label', 'Username')
            .closest('.oxd-input-group')
            .find('input')
            .type(username);
        return this;
    }

    selectUserRole(role) {
        // Label-anchored: finds the User Role dropdown by its label — no .eq() index
        cy.contains('.oxd-label', 'User Role')
            .closest('.oxd-input-group')
            .find('[role="combobox"]')
            .click();
        cy.contains('.oxd-select-option', role).click();
        return this;
    }

    selectStatus(status) {
        // Label-anchored: finds the Status dropdown by its label — no .eq() index
        cy.contains('.oxd-label', 'Status')
            .closest('.oxd-input-group')
            .find('[role="combobox"]')
            .click();
        cy.contains('.oxd-select-option', status).click();
        return this;
    }

    clickSearch() {
        cy.get(this.submitButton).click();
        return this;
    }

    clickReset() {
        // OrangeHRM Reset button has type="button" — use text to disambiguate
        cy.contains('button', 'Reset').click();
        return this;
    }

    clickAdd() {
        // Text-based: survives button style changes
        cy.contains('button', 'Add').click();
        return this;
    }

    verifySearchResults(username) {
        cy.get('.oxd-table-body').should('be.visible');
        cy.contains('.oxd-table-cell', username).should('be.visible');
        return this;
    }

    // --- Add User page ---

    verifyAddUserPage() {
        cy.contains('h6', 'Add User').should('be.visible');
        cy.contains('.oxd-label', 'User Role').should('be.visible');
        cy.contains('.oxd-label', 'Employee Name').should('be.visible');
        cy.contains('.oxd-label', 'Status').should('be.visible');
        cy.contains('.oxd-label', 'Username').should('be.visible');
        cy.contains('.oxd-label', 'Password').should('be.visible');
        cy.contains('.oxd-label', 'Confirm Password').should('be.visible');
        return this;
    }
}

export default new AdminPage();
